krpano.action:
var THREE = (krpano.threejs && krpano.threejs.THREE) ? krpano.threejs.THREE : null;
var cam = (krpano.threejs && krpano.threejs.camera) ? krpano.threejs.camera : null;
if (!THREE || !cam) return;

cam.updateMatrixWorld();

// Camera forward and right, in world space.
var fwd   = new THREE.Vector3(0, 0, -1).applyQuaternion(cam.quaternion);
var right = new THREE.Vector3(1, 0,  0).applyQuaternion(cam.quaternion);

var azimuthOf = function (v) {
	return Math.atan2(v.z, -v.x) * 180 / Math.PI;   // degrees, matches u above
};

var hlookat = Number(krpano.get('view.hlookat'));
var vlookat = Number(krpano.get('view.vlookat'));
if (!isFinite(hlookat) || !isFinite(vlookat)) return;

// Nudge the forward direction toward camera-right: that is the direction krpano
// reaches by INCREASING hlookat, so it tells us the sign without moving the view.
var nudged = fwd.clone().addScaledVector(right, 0.05);
var dA = azimuthOf(nudged) - azimuthOf(fwd);
while (dA >  180) dA -= 360;
while (dA < -180) dA += 360;
var athSign = dA >= 0 ? 1 : -1;

// Elevation of the forward ray vs vlookat gives the vertical sign the same way.
var fl = fwd.length() || 1;
var elevation = Math.asin(Math.max(-1, Math.min(1, fwd.y / fl))) * 180 / Math.PI;
// atv = atvSign * elevation. krpano is positive-DOWN, so this resolves to -1.
var atvSign = 1;
if (Math.abs(vlookat) > 2 && Math.abs(elevation) > 0.5) {
	atvSign = (vlookat * elevation) >= 0 ? 1 : -1;
} else {
	atvSign = -1;   // near the horizon the ratio is noise; use krpano's documented sign
}

var cal = {
	azRef: azimuthOf(fwd),   // canvas azimuth of the current view centre
	athRef: hlookat,         // the ath that same direction has
	athSign: athSign,
	atvSign: atvSign
};

// Published on the krpano object rather than returned: krpano.call() does not
// forward a JS action's return value.
krpano.annotation_cal = cal;

if (!krpano.annotation_cal_logged) {
	krpano.annotation_cal_logged = true;
	try {
		console.log('[annotation_layer] sphere calibration', cal,
			'(atvSign -1 = krpano atv is positive-down, as documented)');
	} catch (e) {}
}

var L = krpano.annotation_layer_refs;
if (!L || !L.ctx) return;
var data = window.__krpanoAnnotations || { strokes: [], laser: null };
var ctx = L.ctx, W = L.W, H = L.H;
ctx.clearRect(0, 0, W, H);

// Same teacher-clock reconciliation the React layer uses: created_ms is stamped on the
// teacher's clock, so a viewer with a fast clock would expire every stroke on arrival.
var now = Date.now() + (Number(window.__krpanoAnnotationClockOffset) || 0);
var all = [];
if (data.strokes) all = all.concat(data.strokes);
if (data.laser) all.push(data.laser);

// Attach the sphere only while there is something to draw, and remove it again
// when the ink is gone, so an idle lesson's 3D scene is identical to before.
var wanted = all.length > 0;
if (wanted && !L.attached && L.group) {
	L.group.add(L.mesh);
	L.attached = true;
} else if (!wanted && L.attached && L.mesh.parent) {
	L.mesh.parent.remove(L.mesh);
	L.attached = false;
}
L.mesh.visible = wanted;
if (!wanted) { if (L.texture) L.texture.needsUpdate = true; return; }

// Re-solve the direction mapping every repaint; it is a few vector ops and it means
// the layer cannot be left using a stale calibration after a re-embed.
krpano.call('annotation_calibrate()');
var cal = krpano.annotation_cal || L.cal;
if (!cal) return;
L.cal = cal;

// (ath, atv) -> canvas pixel. Wrapped so a stroke near the seam still lands.
var toX = function (ath) {
	var a = cal.azRef + cal.athSign * (ath - cal.athRef);
	a = ((a % 360) + 360) % 360;
	return (a / 360) * W;
};
var toY = function (atv) {
	// elevation = atv / atvSign; canvas row 0 is the north pole (elevation +90).
	var elevation = atv / cal.atvSign;
	return ((90 - elevation) / 180) * H;
};

for (var i = 0; i < all.length; i++) {
	var s = all[i];
	if (!s || !s.points || s.points.length < 2) continue;

	// Every stroke is temporary. Keep in sync with STROKE_TTL_MS / laserOpacity
	// in src/lib/annotations/sphereGeometry.ts.
	var alpha = 1;
	var ttl = s.ttl_ms ? s.ttl_ms : 6500;
	var age = now - s.created_ms;
	if (age >= ttl) continue;
	var fadeStart = ttl * 0.6;
	if (age > fadeStart) alpha = 1 - (age - fadeStart) / (ttl - fadeStart);

	ctx.globalAlpha = alpha;
	ctx.strokeStyle = s.color || '#ffdd33';
	ctx.lineWidth = Math.max(4, (s.width || 4) * 3.2);
	ctx.lineCap = 'round';
	ctx.lineJoin = 'round';

	// Split wherever consecutive points jump more than half the canvas in x. That
	// covers both the +/-180 seam in the source data AND the seam introduced by the
	// calibrated rotation, which the old fixed-offset version could not see.
	var runs = [[]];
	var prevX = null;
	for (var p = 0; p < s.points.length; p++) {
		var xp = toX(s.points[p].a);
		if (prevX !== null && Math.abs(xp - prevX) > W / 2) runs.push([]);
		runs[runs.length - 1].push({ x: xp, y: toY(s.points[p].v) });
		prevX = xp;
	}

	for (var r = 0; r < runs.length; r++) {
		var run = runs[r];
		if (run.length < 2) continue;
		ctx.beginPath();
		for (var q = 0; q < run.length; q++) {
			if (q === 0) { ctx.moveTo(run[q].x, run[q].y); } else { ctx.lineTo(run[q].x, run[q].y); }
		}
		ctx.stroke();
	}
}
ctx.globalAlpha = 1;
if (L.texture) L.texture.needsUpdate = true;

if (!krpano.threejs || !krpano.threejs.THREE) return;

// Normally invoked from the hotspot's onloaded, where `caller` IS the hotspot. But
// onloaded is not guaranteed to fire for type="threejs" url="custom", and when it did
// not the layer was never built, annotation_layer_update() returned early forever, and
// every student in a headset saw no ink at all with nothing logged. So fall back to
// locating the hotspot ourselves.
//
// Scan the array BY INDEX. Addressing hotspot[annotation_layer_3d] by name would make
// krpano CREATE it — the phantom-hotspot mechanism that once killed panorama dragging.
var host = (caller && caller.threejsobject && String(caller.name || "") === "annotation_layer_3d")
	? caller
	: null;
if (!host) {
	var hc = Number(krpano.get('hotspot.count')) || 0;
	for (var hi = 0; hi < hc; hi++) {
		var cand = null;
		try { cand = krpano.hotspot.getItem(hi); } catch (e) { cand = null; }
		if (cand && String(cand.name) === "annotation_layer_3d" && cand.threejsobject) { host = cand; break; }
	}
}
if (!host) return;
if (krpano.annotation_layer_refs) return;   // already built

var THREE = krpano.threejs.THREE;
var W = 4096, H = 2048;
var canvas = document.createElement('canvas');
canvas.width = W;
canvas.height = H;
var ctx = canvas.getContext('2d');
ctx.clearRect(0, 0, W, H);

var texture = new THREE.CanvasTexture(canvas);
texture.needsUpdate = true;

// Radius in krpano's THREE world units, where 1 unit = hotspotworldscale cm (100 by
// default, i.e. 1 metre). This was hard-coded to 480 — a number borrowed from krpano's
// ~500-unit panorama sphere, which is a DIFFERENT coordinate space. In three.js units
// that is a 480-METRE sphere, far enough out to sit beyond the camera's far plane and
// be clipped away entirely, which is why the in-headset ink never appeared while the
// immersive panel (which does convert via hotspotworldscale) renders fine.
var ws = (krpano.display && krpano.display.hotspotworldscale) || 100;
var RADIUS_CM = 1000;                    // 10 m: outside any model, well inside any far plane
var radius = RADIUS_CM / ws;
if (!isFinite(radius) || radius <= 0) radius = 10;
// Depth-test off so ink always shows.
var geo = new THREE.SphereGeometry(radius, 64, 32);
var mat = new THREE.MeshBasicMaterial({
	map: texture,
	transparent: true,
	side: THREE.BackSide,
	depthWrite: false,
	depthTest: false
});
var mesh = new THREE.Mesh(geo, mat);
mesh.renderOrder = 999;
// This sphere ENCLOSES the camera, so any raycast over the scene hits it from every
// pointer position. The hotspot is declared hittest="false", and this enforces the
// same intent on the three.js side so the mesh can never swallow a drag or a model
// pick once ink exists.
mesh.raycast = function () {};
// LAZY: do NOT attach the mesh yet. A full-sphere, depth-test-disabled mesh sitting
// in krpano's Three.js scene on every lesson is a change HEAD never had, and the
// scene must stay exactly as it was until there is actually ink to show.
mesh.visible = false;

krpano.annotation_layer_refs = {
	canvas: canvas, ctx: ctx, texture: texture, mesh: mesh,
	group: host.threejsobject, attached: false, W: W, H: H, cal: null,
	radius: radius, worldScale: ws
};

if (window.__krpanoAnnotations) krpano.call('annotation_layer_draw()');

// Build-then-draw. This used to return silently when refs were null, which turned a
// missed onloaded into "students in VR never see ink", with no error anywhere.
if (!krpano.annotation_layer_refs) krpano.call('annotation_layer_build()');
if (krpano.annotation_layer_refs) krpano.call('annotation_layer_draw()');

var L = krpano.annotation_layer_refs;
if (!L) return;
try {
	if (L.mesh && L.mesh.parent) L.mesh.parent.remove(L.mesh);
	if (L.mesh) { L.mesh.geometry.dispose(); L.mesh.material.dispose(); }
	if (L.texture) L.texture.dispose();
} catch (e) {}
krpano.annotation_layer_refs = null;

// Raycast the pointer against every asset_N hotspot. Result is handed back to React
// through a global, matching the __krpanoUIState idiom used elsewhere here.
window.__krpanoModelPick = null;
if (!krpano.threejs || !krpano.threejs.THREE || !krpano.threejs.camera) return;
var THREE = krpano.threejs.THREE;

var px = (typeof args !== 'undefined' && args[1] !== undefined) ? Number(args[1])
	: (krpano.mouse ? krpano.mouse.x : NaN);
var py = (typeof args !== 'undefined' && args[2] !== undefined) ? Number(args[2])
	: (krpano.mouse ? krpano.mouse.y : NaN);

// Read the stage through get() with the bare property only as a fallback. Bare
// property access is not guaranteed on the krpano interface, and an undefined here
// made the NDC NaN, so the raycast silently missed and no pin was ever placed.
var SW = Number(krpano.get('stagewidth')) || Number(krpano.stagewidth);
var SH = Number(krpano.get('stageheight')) || Number(krpano.stageheight);
if (!isFinite(px) || !isFinite(py) || !SW || !SH) return;

var ndc = new THREE.Vector2(
	(px / SW) * 2 - 1,
	-(py / SH) * 2 + 1
);
var raycaster = new THREE.Raycaster();
raycaster.setFromCamera(ndc, krpano.threejs.camera);

// Iterate the EXISTING hotspot array by index. Never address one by name:
// krpano auto-creates an array element on access, so probing asset_0..asset_23
// spawned phantom hotspots that captured pointer events and permanently killed
// panorama dragging the first time the marker was switched on.
var best = null;
var count = Number(krpano.get('hotspot.count')) || 0;
for (var i = 0; i < count; i++) {
	var hs = null;
	try { hs = krpano.hotspot.getItem(i); } catch (e) { hs = null; }
	if (!hs || !hs.name || String(hs.name).indexOf('asset_') !== 0) continue;
	if (!hs.threejsobject) continue;
	// Recursive: a GLB is a group, not a single mesh.
	var hits = raycaster.intersectObject(hs.threejsobject, true);
	if (hits.length > 0) {
		if (!best || hits[0].distance < best.distance) {
			best = { distance: hits[0].distance, point: hits[0].point, root: hs.threejsobject, name: String(hs.name) };
		}
	}
}
if (!best) return;

var local = best.root.worldToLocal(best.point.clone());
window.__krpanoModelPick = { asset_id: best.name, x: local.x, y: local.y, z: local.z };

var THREE = (krpano.threejs && krpano.threejs.THREE) ? krpano.threejs.THREE : null;
if (!THREE) return;
if (!krpano.annotation_mark_objs) krpano.annotation_mark_objs = {};

var data = window.__krpanoAnnotations || {};
var marks = data.model_marks || [];
// Same teacher-clock reconciliation the React layer uses: created_ms is stamped on the
// teacher's clock, so a viewer with a fast clock would expire every stroke on arrival.
var now = Date.now() + (Number(window.__krpanoAnnotationClockOffset) || 0);
var seen = {};

for (var i = 0; i < marks.length; i++) {
	var m = marks[i];
	if (!m || !m.id) continue;
	var ttl = m.ttl_ms ? m.ttl_ms : 6500;
	if (now - m.created_ms >= ttl) continue;
	seen[m.id] = true;

	var obj = krpano.annotation_mark_objs[m.id];
	if (!obj) {
		var hs = null;
		try {
			var hc = Number(krpano.get('hotspot.count')) || 0;
			for (var hi = 0; hi < hc; hi++) {
				var cand = krpano.hotspot.getItem(hi);
				if (cand && String(cand.name) === String(m.asset_id)) { hs = cand; break; }
			}
		} catch (e) { hs = null; }
		if (!hs || !hs.threejsobject) continue;
		var mat = new THREE.SpriteMaterial({
			color: new THREE.Color(m.color || '#ffdd33'),
			depthTest: false,
			depthWrite: false,
			transparent: true
		});
		obj = new THREE.Sprite(mat);
		// Size from the MODEL, not a constant. The sprite is parented to the model's
		// Object3D, so it inherits the model's scale: a fixed 6 local units swallowed a
		// GLB normalised to ~1 unit and vanished inside one authored in centimetres.
		// 4% of the largest bounding-box dimension reads as a pin at any model scale.
		// Measured once and cached: recomputing would include pins already parented to
		// the model and grow the box — and therefore every later pin — on each pick.
		if (!hs.__annotationPinSpan) {
			var box = new THREE.Box3().setFromObject(hs.threejsobject);
			var size = box.getSize(new THREE.Vector3());
			var measured = Math.max(size.x, size.y, size.z);
			hs.__annotationPinSpan = (isFinite(measured) && measured > 0) ? measured : 0;
		}
		var pin = hs.__annotationPinSpan > 0 ? hs.__annotationPinSpan * 0.04 : 1;
		obj.scale.set(pin, pin, pin);
		obj.renderOrder = 1000;
		obj.position.set(m.x, m.y, m.z);
		hs.threejsobject.add(obj);
		krpano.annotation_mark_objs[m.id] = obj;
	}
	// Fade over the last 40% of life, same curve as the sphere strokes.
	var age = now - m.created_ms;
	var fadeStart = ttl * 0.6;
	obj.material.opacity = age > fadeStart ? (1 - (age - fadeStart) / (ttl - fadeStart)) : 1;
}

// Drop anything expired or no longer present.
for (var id in krpano.annotation_mark_objs) {
	if (seen[id]) continue;
	var dead = krpano.annotation_mark_objs[id];
	try {
		if (dead.parent) dead.parent.remove(dead);
		if (dead.material) dead.material.dispose();
	} catch (e) {}
	delete krpano.annotation_mark_objs[id];
}

var out = { ts: Date.now() };
try {
	out.threejs = !!(krpano.threejs && krpano.threejs.THREE);
	out.camera = !!(krpano.threejs && krpano.threejs.camera);
	out.webvrEnabled = String(krpano.get('webvr.isenabled'));
	out.worldScale = (krpano.display && krpano.display.hotspotworldscale) || null;

	// Is the host hotspot present at all? (by index — never by name)
	var count = Number(krpano.get('hotspot.count')) || 0;
	out.hotspotCount = count;
	out.hostHotspot = null;
	for (var i = 0; i < count; i++) {
		var hs = null;
		try { hs = krpano.hotspot.getItem(i); } catch (e) { hs = null; }
		if (hs && String(hs.name) === 'annotation_layer_3d') {
			out.hostHotspot = { index: i, hasThreejsObject: !!hs.threejsobject };
			break;
		}
	}

	var L = krpano.annotation_layer_refs;
	out.layerBuilt = !!L;
	if (L) {
		out.radius = L.radius;
		out.attachedFlag = L.attached;
		out.meshInScene = !!(L.mesh && L.mesh.parent);
		out.meshVisible = !!(L.mesh && L.mesh.visible);
		out.calibration = L.cal || null;
		if (L.mesh) {
			// Walk up to confirm the mesh really reaches the rendered scene graph,
			// and report where it ended up in world space.
			var n = L.mesh, depth = 0, rootType = null;
			while (n.parent && depth < 32) { n = n.parent; depth++; }
			out.ancestorDepth = depth;
			out.rootIsScene = (n && n.type === 'Scene');
			rootType = n ? n.type : null;
			out.rootType = rootType;
			if (krpano.threejs && krpano.threejs.THREE && krpano.threejs.camera) {
				var THREE = krpano.threejs.THREE;
				var cam = krpano.threejs.camera;
				out.cameraNear = cam.near; out.cameraFar = cam.far;
				// Clipped if the sphere sits entirely beyond the far plane.
				out.radiusBeyondFarPlane = (typeof cam.far === 'number') ? (L.radius > cam.far) : null;
				var wp = new THREE.Vector3();
				L.mesh.getWorldPosition(wp);
				out.meshWorldPos = [ +wp.x.toFixed(2), +wp.y.toFixed(2), +wp.z.toFixed(2) ];
				var cp = new THREE.Vector3();
				cam.getWorldPosition(cp);
				out.cameraWorldPos = [ +cp.x.toFixed(2), +cp.y.toFixed(2), +cp.z.toFixed(2) ];
				out.cameraInsideSphere = wp.distanceTo(cp) < L.radius;
			}
		}
	}

	var data = window.__krpanoAnnotations || {};
	out.payload = {
		strokes: (data.strokes || []).length,
		laser: !!data.laser,
		marks: (data.model_marks || []).length,
		clockOffset: Number(window.__krpanoAnnotationClockOffset) || 0
	};
	// How many strokes are actually LIVE right now, on the teacher's clock.
	var now = Date.now() + (Number(window.__krpanoAnnotationClockOffset) || 0);
	var live = 0, all = (data.strokes || []).concat(data.laser ? [data.laser] : []);
	for (var k = 0; k < all.length; k++) {
		var st = all[k]; if (!st) continue;
		if (now - st.created_ms < (st.ttl_ms || 6500)) live++;
	}
	out.payload.liveNow = live;
} catch (e) {
	out.error = String(e && e.message ? e.message : e);
}
window.__krpanoAnnotationDiag = out;
try { console.log('[annotation_layer] diagnose', out); } catch (e) {}
